h1 { max-width: 760px; margin: 0; font-family: Georgia, serif; font-size: clamp(44px, 7vw, 72px); font-weight: 500; line-height: .98; letter-spacing: -.04em; }
.intro { max-width: 620px; margin: 24px 0 35px; color: var(--muted); font-size: 18px; line-height: 1.6; }

.save-form { padding: 18px; background: var(--card); border: 1px solid var(--line); border-radius: 18px; box-shadow: 0 16px 45px rgba(35, 48, 40, .08); }
.save-form label { display: block; margin-bottom: 9px; font-size: 12px; font-weight: 750; }
.save-row { display: flex; gap: 10px; }
.save-row input { flex: 1; min-width: 0; height: 52px; border: 1px solid #cbd0c8; border-radius: 10px; padding: 0 15px; color: var(--ink); background: white; outline: none; }
.save-row input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(35,77,59,.13); }
