.section-heading h2 { margin: 0; font-family: Georgia, serif; font-size: 30px; font-weight: 500; }
.count { color: var(--muted); font-size: 13px; }
.empty-state { padding: 60px 20px; border: 1px dashed #c9cdc4; border-radius: 16px; text-align: center; }
.empty-icon { width: 46px; height: 46px; margin: 0 auto 16px; border-radius: 50%; display: grid; place-items: center; background: var(--green-light); color: var(--green); font-size: 25px; }
.empty-state h3 { margin: 0 0 8px; font-family: Georgia, serif; font-size: 21px; }
.empty-state p { margin: 0; color: var(--muted); }

