 *{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit}.app-shell{min-height:100vh;display:grid;grid-template-columns:230px 1fr}.sidebar{position:sticky;top:0;height:100vh;padding:27px 20px;border-right:1px solid var(--line);background:#eeeee7}.logo{display:flex;align-items:center;gap:10px;margin:0 8px 40px;color:var(--ink);font-family:Georgia,serif;font-size:22px;font-weight:700;text-decoration:none}.logo span{width:34px;height:34px;display:grid;place-items:center;border-radius:10px 3px;background:var(--green);color:white}.view-nav,.tag-nav{display:grid;gap:5px}.nav-item,.tag-filter{border:0;border-radius:9px;padding:10px 11px;display:flex;justify-content:space-between;background:transparent;color:var(--muted);cursor:pointer;text-align:left;font-size:13px}.nav-item.active,.tag-filter.active,.nav-item:hover,.tag-filter:hover{background:var(--surface);color:var(--green)}.nav-item b{font-size:11px}.tag-nav{margin-top:35px}.tag-nav h2{margin:0 11px 7px;color:#8a928d;font-size:10px;letter-spacing:.13em;text-transform:uppercase}.tag-nav>button,.tag-nav #tag-list button{width:100%}.main{width:min(1050px,calc(100% - 64px));margin:0 auto;padding:70px 0 120px}.page-header{display:flex;align-items:end;justify-content:space-between;gap:24px}.kicker{margin:0 0 10px;color:var(--amber);font-size:10px;font-weight:800;letter-spacing:.17em}.page-header h1{margin:0;font-family:Georgia,serif;font-size:clamp(40px,6vw,62px);font-weight:500;letter-spacing:-.035em}.page-header p:last-child{margin:13px 0 0;color:var(--muted)}.save-open{border:0;border-radius:10px;padding:12px 17px;background:var(--green);color:white;cursor:pointer;font-weight:750}.save-panel{margin-top:28px;padding:17px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow)}.save-panel label{display:block;margin-bottom:8px;font-size:12px;font-weight:750}.save-line{display:flex;gap:9px}.save-line input{flex:1;min-width:0;height:48px;border:1px solid #b8c0b8;border-radius:9px;padding:0 13px;outline:0}.save-line input:focus{border-color:var(--green);box-shadow:0 0 0 3px rgba(37,85,63,.12)}.save-line input.error{border-color:var(--danger)}.save-line button{border:0;border-radius:9px;padding:0 17px;background:var(--green);color:white;cursor:pointer;font-weight:750}.save-line button:disabled{opacity:.6}.field-error{margin:8px 0 0;color:var(--danger);font-size:12px;font-weight:700}.tools{display:flex;gap:12px;margin-top:38px;padding:14px 0;border-block:1px solid var(--line)}.search{position:relative;flex:1}.search span{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted)}.search input{width:100%;height:42px;border:1px solid #c1c8c0;border-radius:9px;padding:0 12px 0 36px;background:var(--surface);outline:0}.sort-label{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:11px}.sort-label select{height:42px;border:1px solid #c1c8c0;border-radius:9px;padding:0 29px 0 10px;background:var(--surface);color:var(--ink)}.result-line{display:flex;justify-content:space-between;margin:22px 0 12px;color:var(--muted);font-size:12px}.result-line span:first-child{color:var(--ink);font-weight:750}.bookmark-list{display:grid;gap:13px}.bookmark-card{position:relative;display:grid;grid-template-columns:auto 190px minmax(0,1fr) auto;gap:16px;padding:13px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:0 7px 24px rgba(30,45,36,.04)}.bookmark-card.selected{border-color:#76a087;box-shadow:0 0 0 3px rgba(37,85,63,.1)}.select-bookmark{width:17px;height:17px;margin:6px 0;accent-color:var(--green);cursor:pointer}.card-media{min-height:145px;overflow:hidden;display:grid;place-items:center;border-radius:9px;background:linear-gradient(145deg,#dfe9e1,#efc99b);color:var(--green);font-size:26px}.card-media img{width:100%;height:100%;object-fit:cover}.card-content{align-self:center;min-width:0}.site-row{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:11px}.site-icon{width:20px;height:20px;border-radius:5px;object-fit:contain}.card-content h2{margin:8px 0 7px;font-family:Georgia,serif;font-size:22px;font-weight:500;line-height:1.2}.bookmark-title{color:var(--ink);text-decoration:none}.bookmark-title:hover{text-decoration:underline}.bookmark-description{margin:0 0 10px;color:var(--muted);font-size:13px;line-height:1.45}.fallback-notice{margin:0 0 9px;padding:7px 9px;border-radius:7px;background:#f4eadc;color:#805335;font-size:11px}.tag-row{display:flex;flex-wrap:wrap;gap:5px;margin:0 0 9px}.tag-pill{border:0;border-radius:999px;padding:5px 8px;background:var(--pale);color:var(--green);cursor:pointer;font-size:10px;font-weight:750}.note-block{margin:8px 0;padding:8px 10px;border-left:3px solid var(--amber);background:#f4ede3;color:#49554d;font-size:11px;white-space:pre-wrap}.bookmark-url{overflow:hidden;margin:0;color:#8a928d;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.card-actions{position:relative;display:flex;align-items:flex-start;gap:5px}.read-later-action{border:1px solid #b2bdb4;border-radius:8px;padding:8px 9px;background:transparent;color:var(--green);cursor:pointer;font-size:10px;font-weight:750}.read-later-action.active{background:var(--pale)}.more-action{width:36px;height:36px;border:0;border-radius:8px;background:transparent;color:var(--muted);cursor:pointer}.more-action:hover{background:#eff0ea}.card-menu{position:absolute;z-index:5;right:0;top:40px;width:190px;padding:5px;border:1px solid var(--line);border-radius:10px;background:white;box-shadow:0 12px 28px rgba(0,0,0,.13)}.card-menu button{width:100%;border:0;border-radius:7px;padding:9px;background:transparent;color:var(--ink);cursor:pointer;text-align:left;font-size:11px}.card-menu button:hover{background:#eef1ec}.card-menu .danger-text{color:var(--danger)}.inline-editor{margin-top:9px}.inline-editor label{display:block;margin:8px 0 4px;color:var(--muted);font-size:10px;font-weight:750}.inline-editor input,.inline-editor textarea{width:100%;border:1px solid #afb9b0;border-radius:8px;padding:8px;background:white;color:var(--ink)}.inline-actions{display:flex;justify-content:flex-end;gap:7px;margin-top:8px}.primary,.secondary,.danger{border-radius:8px;padding:9px 12px;cursor:pointer;font-size:11px;font-weight:750}.primary{border:1px solid var(--green);background:var(--green);color:white}.secondary{border:1px solid #bac2bb;background:transparent;color:var(--ink)}.danger{border:1px solid var(--danger);background:var(--danger);color:white}.danger-text{color:#ffc5bd!important}.empty-state{margin-top:10px;padding:70px 24px;border:1px dashed #c3c8c1;border-radius:15px;text-align:center}.empty-symbol{width:48px;height:48px;margin:0 auto 16px;display:grid;place-items:center;border-radius:50%;background:var(--pale);color:var(--green);font-size:24px}.empty-state h2{margin:0 0 8px;font-family:Georgia,serif;font-size:24px;font-weight:500}.empty-state p{margin:0;color:var(--muted)}.bulk-bar{position:fixed;z-index:8;left:50%;bottom:25px;transform:translateX(-50%);width:min(650px,calc(100% - 24px));display:flex;align-items:center;gap:7px;padding:11px;border-radius:13px;background:var(--ink);color:white;box-shadow:0 15px 40px rgba(0,0,0,.25)}.bulk-bar strong{margin-right:auto;padding-left:5px;font-size:12px}.bulk-bar button{border:0;border-radius:8px;padding:9px 11px;background:#34453b;color:white;cursor:pointer;font-size:11px;font-weight:750}.toast{position:fixed;z-index:20;right:24px;bottom:24px;max-width:390px;padding:13px 16px;border-radius:11px;background:var(--ink);color:white;box-shadow:0 12px 30px rgba(0,0,0,.2);font-size:12px}.dialog-layer{position:fixed;z-index:15;inset:0;display:grid;place-items:center;padding:20px;background:rgba(19,30,24,.43)}.dialog{width:min(470px,100%);max-height:calc(100vh - 40px);overflow:auto;padding:28px;border-radius:15px;background:var(--paper);box-shadow:0 24px 70px rgba(0,0,0,.25)}.dialog h2{margin:0 0 9px;font-family:Georgia,serif;font-size:29px;font-weight:500}.dialog>p{margin:0 0 15px;color:var(--muted);font-size:13px;line-height:1.5}.dialog label{display:block;margin:14px 0 6px;font-size:11px;font-weight:750}.dialog input,.dialog textarea{width:100%;border:1px solid #afb9b0;border-radius:8px;padding:10px;background:white;color:var(--ink)}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:22px}.suggestions{margin-top:6px;overflow:hidden;border:1px solid var(--line);border-radius:9px;background:white}.suggestions button{width:100%;display:flex;justify-content:space-between;border:0;padding:9px 10px;background:transparent;cursor:pointer;text-align:left;font-size:12px}.suggestions button:hover{background:#edf1ed}.suggestions small{color:var(--muted)}.create-tag{border-top:1px solid var(--line)!important;color:var(--green);font-weight:750}.warning{color:var(--danger)!important;font-weight:750}

